before:
Complete local C example; the app itself does not execute it:
```c
#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

int main(void) {
    const char *text = "12x";
    char *end;
    errno = 0;
    long value = strtol(text, &end, 10);
    if (errno == ERANGE) puts("out of range");
    else if (end == text || *end != '\0') puts("invalid integer");
    else printf("%ld\n", value);
    return 0;
}
```

